def dinic_max_flow(n_nodes, source, sink, edges_list):
    """Dinic's algorithm for max flow"""
    N = n_nodes

    # Build adjacency list
    adj = [[] for _ in range(N)]

    class Edge:
        def __init__(self, to, capacity, rev):
            self.to = to
            self.capacity = capacity
            self.rev = rev
            self.flow = 0

    def add_edge(u, v, cap):
        adj[u].append(Edge(v, cap, len(adj[v])))
        adj[v].append(Edge(u, 0, len(adj[u]) - 1))

    # Build graph
    for u, v, cap in edges_list:
        add_edge(u, v, cap)

    # BFS for level graph
    def bfs():
        level = [-1] * N
        level[source] = 0
        queue = [source]
        while queue:
            u = queue.pop(0)
            for e in adj[u]:
                if e.capacity - e.flow > 0 and level[e.to] < 0:
                    level[e.to] = level[u] + 1
                    queue.append(e.to)
        return level

    # DFS for blocking flow
    def dfs(u, sink, f, level, ptr):
        if u == sink:
            return f
        for i in range(ptr[u], len(adj[u])):
            ptr[u] = i
            e = adj[u][i]
            if e.capacity - e.flow > 0 and level[u] < level[e.to]:
                ret = dfs(e.to, sink, min(f, e.capacity - e.flow), level, ptr)
                if ret > 0:
                    e.flow += ret
                    adj[e.to][e.rev].flow -= ret
                    return ret
        return 0

    max_flow = 0
    while True:
        level = bfs()
        if level[sink] < 0:
            break
        ptr = [0] * N
        while True:
            pushed = dfs(source, sink, float('inf'), level, ptr)
            if pushed == 0:
                break
            max_flow += pushed

    return max_flow

