    # Build constraint graph for topological sort
    # LEFT: b in a's left subtree -> in-order: b comes before a -> edge b -> a
    # RIGHT: b in a's right subtree -> in-order: a comes before b -> edge a -> b
    adj = {i: [] for i in range(1, n + 1)}
