            adj[b].append(a)
            in_degree[a] += 1
        else:
            # a must come before b
            adj[a].append(b)
            in_degree[b] += 1

    # Topological sort (Kahn's algorithm)
    topo_order = []
    for i in range(1, n + 1):
        if in_degree[i] == 0:
