def solution(input_str):
    try:
        n, l, r = map(int, input_str.strip().split())
    except:
        return "0"

    # Case 1: n = 1, any number in [l, r] is a valid sequence
    if n == 1:
        return str(r - l + 1)

    # Case 2: n = 2, any pair of distinct numbers works
    if n == 2:
        return str((r - l + 1) * (r - l))

    # Case 3: n >= 3, count geometric progressions
    count = 0

    # Precompute powers for efficiency
    pow_q = {}
    pow_p = {}

    for p in range(2, r + 1):
        for q in range(1, p):
            # Skip non-coprime pairs
            g = 0
            a, b = p, q
            while b:
                a, b = b, a % b
                g = b

            if g != 1:
                continue

            # Check if all terms can fit in [l, r]
            # a * (p/q)^(n-1) <= r for a >= l
            # This means (p/q)^(n-1) >= l/r

            # For large n, this check fails quickly
            if n >= 10000:
                # For very large n, only small ratios work
                if p > 10:
                    continue

            # Calculate p^(n-1) and q^(n-1)
            p_pow = 1
            q_pow = 1
            for _ in range(n - 1):
                p_pow *= p
                if p_pow > r * 1000:  # Early termination if too large
                    break
                q_pow *= q
                if p_pow > r * 1000:
                    break
                if p_pow > r * 1000 or q_pow > r * 1000:
                    break

            if p_pow > r * 1000 or q_pow > r * 1000:
                continue

            # Upper bound for starting value a: floor(r * q^(n-1) / p^(n-1))
            max_a = (r * q_pow) // p_pow

            if max_a >= l:
                count += max_a - l + 1

    return str(count)
